import { z } from "zod";
import type { CategoryInput } from "@aurascenthaus/shared";

export const categoryFormSchema = z.object({
  name: z.string().trim().min(1, "Enter a name").max(80),
  description: z.string().trim().max(500),
});
export type CategoryFormValues = z.infer<typeof categoryFormSchema>;

export const EMPTY_CATEGORY: CategoryFormValues = { name: "", description: "" };

/** The URL slug is generated by the API from the name. */
export function toCategoryInput(values: CategoryFormValues): CategoryInput {
  return { name: values.name, description: values.description || undefined };
}
